async function fetchJson(endpoint) {
  try {
    if (typeof fetch === 'function') {
      const res = await fetch(`${apiBase}${endpoint}`);
      if (res.ok) return await res.json();
    }
  } catch (err) {
    // fallback to static context
  }
  return null;
}

let resultData = {};
let success = true;
let error = null;

try {
  switch (tool) {
    case 'project_info': {
      let projects = await fetchJson('/projects');
      if (!Array.isArray(projects) || projects.length === 0) {
        projects = fallbackProjects;
      }
      if (projectId) {
        const found = projects.find(p => p.id === projectId || p.code === projectId || (p.title && p.title.toLowerCase().includes(projectId.toLowerCase())));
        if (found) {
          resultData = found;
        } else {
          resultData = { requestedId: projectId, availableProjects: projects.map(p => ({ id: p.id, title: p.title, code: p.code, progress: p.progress, phase: p.phase, scale: p.scale })) };
        }
      } else {
        resultData = { total: projects.length, projects: projects.map(p => ({ id: p.id, title: p.title, code: p.code, progress: p.progress, phase: p.phase, category: p.category, scale: p.scale, nextMilestone: p.nextMilestone })) };
      }
      break;
    }

    case 'project_progress': {
      let projects = await fetchJson('/projects');
      if (!Array.isArray(projects) || projects.length === 0) projects = fallbackProjects;
      const targetProject = projectId ? (projects.find(p => p.id === projectId || p.code === projectId) || projects[0]) : projects[0];
      const targetId = targetProject ? targetProject.id : projectId;

      let milestones = (await fetchJson(`/milestones?projectId=${targetId}`)) || [
        { id: 'm-1', title: targetProject?.nextMilestone || 'Portfolio review', date: '2026-11-18', status: 'pending' }
      ];
      let updates = (await fetchJson(`/updates?projectId=${targetId}`)) || [
        { id: 'u-1', title: 'Phase update', date: '2026-10-01', summary: `${targetProject?.title || 'Project'} progress is at ${targetProject?.progress || 74}%` }
      ];
      let snapshots = (await fetchJson(`/progressSnapshots?projectId=${targetId}`)) || [];

      resultData = {
        project: targetProject ? { id: targetProject.id, title: targetProject.title, progress: targetProject.progress, phase: targetProject.phase, nextMilestone: targetProject.nextMilestone } : { id: projectId },
        milestones,
        updates,
        snapshots
      };
      break;
    }

    case 'project_documents': {
      let docs = await fetchJson(projectId ? `/documents?projectId=${projectId}` : '/documents');
      if (!Array.isArray(docs) || docs.length === 0) {
        docs = [
          { id: 'doc-01', title: 'Executive Project Dossier', projectId: projectId || 'zona-franca-la-lima', type: 'PDF', status: 'approved' },
          { id: 'doc-02', title: 'BIM Technical Specifications & IFC Model', projectId: projectId || 'zona-franca-la-lima', type: 'IFC', status: 'active' },
          { id: 'doc-03', title: 'LEED & Sustainability Certification Filing', projectId: projectId || 'zona-franca-la-lima', type: 'PDF', status: 'in-review' }
        ];
      }
      resultData = { projectId: projectId || 'all', count: docs.length, documents: docs };
      break;
    }

    case 'project_approvals': {
      let approvals = await fetchJson(projectId ? `/approvals?projectId=${projectId}` : '/approvals');
      if (!Array.isArray(approvals) || approvals.length === 0) {
        approvals = [
          { id: 'app-01', title: 'Structural & Envelope Verification Signoff', projectId: projectId || 'zona-franca-la-lima', status: 'pending', requestedBy: 'Architect Lead' },
          { id: 'app-02', title: 'Fire & Life Safety Compliance Approval', projectId: projectId || 'zona-franca-la-lima', status: 'approved', requestedBy: 'Engineering Lead' }
        ];
      }
      resultData = { projectId: projectId || 'all', count: approvals.length, approvals };
      break;
    }

    case 'project_analytics': {
      let projects = await fetchJson('/projects');
      if (!Array.isArray(projects) || projects.length === 0) projects = fallbackProjects;
      let approvals = await fetchJson('/approvals') || [];
      let milestones = await fetchJson('/milestones') || [];

      const totalProjects = projects.length;
      const avgProgress = Math.round(projects.reduce((sum, p) => sum + (p.progress || 0), 0) / (totalProjects || 1));
      const pendingApprovals = approvals.filter(a => a.status === 'pending').length;
      const upcomingMilestones = milestones.filter(m => m.status === 'pending').length;

      resultData = {
        totalProjects,
        averageProgress: avgProgress,
        pendingApprovalsCount: pendingApprovals,
        upcomingMilestonesCount: upcomingMilestones,
        activeProjects: projects.map(p => ({ id: p.id, title: p.title, progress: p.progress, phase: p.phase }))
      };
      break;
    }

    case 'bim_metadata': {
      resultData = {
        supportedSchemas: ['IFC4', 'IFC2X3'],
        geometryEngine: 'That Open Engine / WebGL Fragments',
        features: [
          'Spatial Tree Navigation (IfcProject, IfcSite, IfcBuilding, IfcBuildingStorey, IfcSpace, IfcElement)',
          'High-precision Property Sets extraction',
          'Fast raycast element selection and multi-element isolation/hide',
          'Orthographic & Perspective architectural camera presets',
          '3-axis live section clipping planes',
          'Point-to-point 3D laser measurement tool',
          'PBR architectural material textures (La Lima concrete, steel, architectural glass, cedar)',
          'ChangeSet tracking and local revision persistence'
        ],
        currentProjectId: projectId || 'zona-franca-la-lima'
      };
      break;
    }

    case 'user_context': {
      resultData = {
        role: role,
        permissions: {
          viewProjects: true,
          viewDocuments: true,
          submitApprovals: role === 'admin' || role === 'client',
          editBimModels: role === 'admin' || role === 'architect',
          viewAnalytics: role === 'admin' || role === 'architect'
        },
        description: `Authenticated ${role} user session with active project context.`
      };
      break;
    }

    case 'navigation_context': {
      resultData = {
        routes: [
          { path: '/', label: 'Public Architecture Showcase' },
          { path: '/portfolio', label: 'Development Portfolio' },
          { path: '/portal', label: 'Executive Command Center' },
          { path: '/portal/projects', label: 'Project Register' },
          { path: '/portal/approvals', label: 'Executive Approvals & Signoffs' },
          { path: '/portal/documents', label: 'Document & Specification Vault' },
          { path: '/portal/analytics', label: 'Portfolio Analytics & KPIs' },
          { path: '/portal/news', label: 'News & Announcements Desk' },
          { path: '/workspace', label: '3D BIM Engineering Workspace' }
        ]
      };
      break;
    }

    default: {
      success = false;
      error = `Unsupported tool operation: ${tool}`;
      resultData = { requestedTool: tool, supportedTools: ['project_info', 'project_progress', 'project_documents', 'project_approvals', 'project_analytics', 'bim_metadata', 'user_context', 'navigation_context'] };
    }
  }
} catch (e) {
  success = false;
  error = String(e.message || e);
}

return [{
  json: {
    success,
    tool,
    data: resultData,
    error
  }
}];
